<?php
declare(strict_types=1);
umask(0077);
ini_set('display_errors','0');
const PRIVATE_DIR=__DIR__;
function config(): array { static $c; if(!$c){if(!is_file(PRIVATE_DIR.'/config.php'))throw new RuntimeException('Portal ainda não instalado.');$c=require PRIVATE_DIR.'/config.php';} return $c; }
function sql(): PDO {static $db;if(!$db){$db=new PDO('sqlite:'.PRIVATE_DIR.'/portal.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('PRAGMA busy_timeout=5000; PRAGMA foreign_keys=ON');}return $db;}
function query(string $q,array $p=[]): PDOStatement {$s=sql()->prepare($q);$s->execute($p);return $s;}
function sealed(string $text): string {$key=hex2bin(config()['data_key']);$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return base64_encode($nonce.sodium_crypto_secretbox($text,$nonce,$key));}
function unsealed(string $data): string {$raw=base64_decode($data,true);if($raw===false)throw new RuntimeException('Dados inválidos.');$nonce=substr($raw,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$out=sodium_crypto_secretbox_open(substr($raw,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),$nonce,hex2bin(config()['data_key']));if($out===false)throw new RuntimeException('Falha de integridade.');return $out;}
function state_record(): array {$r=query('SELECT revision,data FROM state WHERE id=1')->fetch(PDO::FETCH_ASSOC);return ['revision'=>(int)$r['revision'],'data'=>json_decode(unsealed($r['data']),true,512,JSON_THROW_ON_ERROR)];}
function headers_private(): void {header('X-Robots-Tag: noindex, nofollow, nosnippet');header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header('X-Frame-Options: DENY');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; frame-src https://maps.google.com; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'");}
function start_session(): void {if(session_status()===PHP_SESSION_ACTIVE)return;$https=($_SERVER['HTTPS']??'')==='on';$local=getenv('SION_LOCAL_TEST')==='1'&&PHP_SAPI==='cli-server';if(!$https&&!$local){http_response_code(403);exit('Acesse o portal por HTTPS.');}if(!is_dir(PRIVATE_DIR.'/sessions'))mkdir(PRIVATE_DIR.'/sessions',0700);session_save_path(PRIVATE_DIR.'/sessions');session_name('sion_portal');session_set_cookie_params(['lifetime'=>0,'path'=>parse_url(config()['base_url'],PHP_URL_PATH)?:'/reports','secure'=>!$local,'httponly'=>true,'samesite'=>'Strict']);ini_set('session.use_strict_mode','1');session_start();$_SESSION['csrf']=$_SESSION['csrf']??bin2hex(random_bytes(32));headers_private();}
function csrf(): void {if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??$_SERVER['HTTP_X_CSRF_TOKEN']??'')){http_response_code(403);exit('Sessão expirada. Atualize a página.');}}
function current_user(): ?array {if(empty($_SESSION['uid'])||time()-($_SESSION['seen']??0)>3600||time()-($_SESSION['started']??0)>43200)return null;$u=query('SELECT id,name,email,role,owner_ids,blocked,session_version FROM users WHERE id=?',[$_SESSION['uid']])->fetch(PDO::FETCH_ASSOC);if(!$u||$u['blocked']||(int)$u['session_version']!==($_SESSION['sv']??-1))return null;$u['ownerIds']=json_decode($u['owner_ids'],true);if(!in_array($u['role'],['admin','editor'],true)){$d=state_record()['data'];$u['ownerIds']=array_values(array_filter($u['ownerIds'],function($id)use($d){foreach($d['owners'] as $o)if($o['id']===$id)return empty($o['blocked']);return false;}));if(!$u['ownerIds'])return null;}$_SESSION['seen']=time();unset($u['owner_ids']);$u['blocked']=(bool)$u['blocked'];return $u;}
function need_user(bool $write=false): array {$u=current_user();if(!$u){http_response_code(401);exit('Acesso não autorizado. Entre novamente.');}if($write&&!in_array($u['role'],['admin','editor'],true)){http_response_code(403);exit('Somente consulta.');}return $u;}
function public_user(array $u): array {return array_intersect_key($u,array_flip(['id','name','email','role','ownerIds','blocked']));}
function visible_data(array $u,array $d): array {if(!in_array($u['role'],['admin','editor'],true)){$ids=$u['ownerIds'];$d['owners']=array_values(array_filter($d['owners'],fn($o)=>in_array($o['id'],$ids,true)));$d['properties']=array_values(array_filter($d['properties'],fn($p)=>in_array($p['ownerId'],$ids,true)));foreach($d['properties'] as &$p)unset($p['listing']);unset($p);$d['reports']=array_values(array_filter($d['reports'],fn($r)=>in_array($r['ownerId'],$ids,true)&&($r['status']==='published'||!empty($r['historical']))));$d['hoa']=array_values(array_filter($d['hoa']??[],fn($r)=>in_array($r['ownerId'],$ids,true)&&$r['status']==='published'));$visibleReports=array_column($d['reports'],'id');$d['historicalOccupancy']=array_intersect_key($d['historicalOccupancy']??[],array_flip($visibleReports));unset($d['annual'],$d['trash']);}$d['users']=[public_user($u)];return $d;}
function rate_limit(string $purpose,string $identifier,int $limit=8): bool {$key=hash('sha256',$purpose.'|'.strtolower($identifier).'|'.($_SERVER['REMOTE_ADDR']??''));$cut=time()-900;query('DELETE FROM attempts WHERE created<?',[$cut]);$n=(int)query('SELECT COUNT(*) FROM attempts WHERE key_hash=? AND created>=?',[$key,$cut])->fetchColumn();if($n>=$limit)return false;query('INSERT INTO attempts(key_hash,created) VALUES(?,?)',[$key,time()]);return true;}
function password_ok(string $s): bool {return strlen($s)>=12&&strlen($s)<=256;}
function send_access(array $u): bool {$token=bin2hex(random_bytes(32));query('DELETE FROM tokens WHERE user_id=?',[$u['id']]);query('INSERT INTO tokens(hash,user_id,expires) VALUES(?,?,?)',[hash('sha256',$token),$u['id'],time()+3600]);$url=config()['base_url'].'/?mode=reset&token='.$token;$body="Olá,\n\nUse o link abaixo para definir sua senha no Sion Owners Portal. Ele expira em uma hora e funciona uma única vez.\n\n".$url."\n\nSe você não solicitou este acesso, ignore esta mensagem.\nSion Realty & Property Management";return mail($u['email'],'Sion Owners Portal - definir senha',$body,"From: ".config()['mail_from']."\r\nContent-Type: text/plain; charset=UTF-8");}
function html(string $s): string {return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
